class Solution:
    def maximumMedianSum(self, nums):
        nums.sort()
        return sum(nums[len(nums) - 2 - 2 * i] for i in range(len(nums) // 3))

c.cpp:
class Solution {
public:
    long long maximumMedianSum(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        long long ans = 0;
        int n = nums.size();
        for (int i = n - 2; i >= 0; i -= 2) ans += nums[i];
        return ans;
    }
};

